sys_script.script:
(function() {
    var issued = parseFloat(current.getValue('quantity_issued')) || 0;
    var consumed = parseFloat(current.getValue('quantity_consumed')) || 0;
    var returned = parseFloat(current.getValue('quantity_returned')) || 0;

    // Validate no negative quantities
    if (issued < 0 || consumed < 0 || returned < 0) {
        gs.addErrorMessage('Quantities cannot be negative');
        current.setAbortAction(true);
        return;
    }

    // Validate consumed + returned <= issued
    if ((consumed + returned) > issued) {
        gs.addErrorMessage('Quantity Consumed (' + consumed + ') + Quantity Returned (' + returned + ') cannot exceed Quantity Issued (' + issued + ')');
        current.setAbortAction(true);
        return;
    }

    // Calculate variance
    var variance = issued - consumed - returned;
    current.setValue('quantity_variance', variance);
})();
